    public class SuperBalanceService : ISuperBalanceService
    {
        private const string superBalanceTotal = "superBalanceTotal";
        private readonly IBalanceAccess _balanceAccess;

        public SuperBalanceService():this(null)
        {
            
        }

        public SuperBalanceService(IBalanceAccess balanceAccess)
        {
            this._balanceAccess = balanceAccess ?? new BalanceAccess();
        }


        public string GetSuperBalanceTotal(string db, bool isYesterday, string usernameSearch, string firstletter, string currency)
        {
            var total = 0.0;
            try
            {
                DataTable dtSuperBalace = _balanceAccess.GetSuperBalanceData(db, isYesterday, usernameSearch, firstletter, currency);
                foreach (DataRow row in dtSuperBalace.Rows)
                {
                    total += CastAide.AsDouble(NumberFormat.DecFormat(row["basebalance"], 2));
                }
                SessionExtension.AddSession(HttpContext.Current.Session, superBalanceTotal, total);
            }
            catch (Exception exception)
            {
                LogExtensions.ExceptionHandler(exception);
            }

            return NumberFormat.DecFormat(total, 2);
        }

